Problem:
Bold Tycoon wants to put his $10,000 to work and decides to invest his money in GICs and index ETF. GICs  yields a 2% return whereas index ETF yields an average return of 7.5%. To meet his long-term investment goal, he needs to place at least $4,000 in index ETF.  Nonetheless, he is risk averse and wants at least 30% of his money to be safely invested in GICs.  Help Bold Tycoon determine an asset allocation that will maximize his average return.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "GIC dollars invested",
    "lower": 0.0,
    "upper": null,
    "integer": false
   },
   {
    "name": "index ETF dollars invested",
    "lower": 0.0,
    "upper": null,
    "integer": false
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "GIC dollars invested",
     "coef": 0.02
    },
    {
     "var": "index ETF dollars invested",
     "coef": 0.075
    }
   ]
  },
  "constraints": [
   {
    "name": "budget",
    "terms": [
     {
      "var": "GIC dollars invested",
      "coef": 1.0
     },
     {
      "var": "index ETF dollars invested",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 10000.0
   },
   {
    "name": "minimum ETF investment",
    "terms": [
     {
      "var": "index ETF dollars invested",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 4000.0
   },
   {
    "name": "minimum safe GIC allocation",
    "terms": [
     {
      "var": "GIC dollars invested",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 3000.0
   }
  ]
 },
 "facts": {
  "objective": 585.0,
  "values": {
   "GIC dollars invested": 3000.0,
   "index ETF dollars invested": 7000.0
  },
  "binding": [
   "budget",
   "minimum safe GIC allocation"
  ],
  "slack": {
   "budget": 0.0,
   "minimum ETF investment": 3000.0,
   "minimum safe GIC allocation": 0.0
  },
  "shadow_prices": {
   "budget": 0.075,
   "minimum ETF investment": 0.0,
   "minimum safe GIC allocation": -0.055
  }
 }
}
